"use client";

import {
  MultiReferencePicker,
  type PickedReference,
  type ReferenceOption,
} from "@/components/admin/multi-reference-picker";
import { createArtistInline } from "@/app/(admin)/artists/actions";
import { createWriterInline } from "@/app/(admin)/writers/actions";
import { createLabelInline } from "@/app/(admin)/labels/actions";

const fieldClasses =
  "w-full rounded-[var(--radius-control)] border border-console-border bg-console-bg px-3 py-2 text-sm text-console-text placeholder:text-console-text-muted focus:border-console-accent";

export function SongForm({
  defaultValues,
  referenceData,
  action,
  submitLabel,
}: {
  defaultValues?: {
    title: string;
    cover_art_url: string | null;
    notes: string | null;
    artists: ReferenceOption[];
    writers: PickedReference[];
    labels: PickedReference[];
  };
  referenceData: {
    artists: ReferenceOption[];
    writers: ReferenceOption[];
    labels: ReferenceOption[];
  };
  action: (formData: FormData) => void;
  submitLabel: string;
}) {
  return (
    // PRD §3 song detail layout: core details, then Writers, then Labels,
    // Notes last. Audio preview (also part of that layout) arrives with
    // Spotify integration in Phase 3.
    <form action={action} className="max-w-xl space-y-8">
      <div className="space-y-5">
        <div>
          <label htmlFor="title" className="mb-1 block text-sm text-console-text-muted">
            Title
          </label>
          <input
            id="title"
            name="title"
            required
            defaultValue={defaultValues?.title}
            className={fieldClasses}
            placeholder="Song title"
          />
        </div>

        <div>
          <label
            htmlFor="cover_art_url"
            className="mb-1 block text-sm text-console-text-muted"
          >
            Cover art URL
          </label>
          <input
            id="cover_art_url"
            name="cover_art_url"
            type="url"
            defaultValue={defaultValues?.cover_art_url ?? ""}
            className={fieldClasses}
            placeholder="https://…"
          />
          <p className="mt-1 text-xs text-console-text-muted">
            Manual for now — Spotify auto-fetch arrives in Phase 3.
          </p>
        </div>

        <div>
          <label className="mb-1 block text-sm text-console-text-muted">Artists</label>
          <MultiReferencePicker
            label="Artists"
            options={referenceData.artists}
            initialSelected={defaultValues?.artists ?? []}
            createAction={createArtistInline}
            hiddenFieldName="artist_ids"
          />
        </div>
      </div>

      <div className="border-t border-console-border pt-6">
        <h2 className="mb-3 text-sm font-medium">Writers</h2>
        <MultiReferencePicker
          label="Writers"
          options={referenceData.writers}
          initialSelected={defaultValues?.writers ?? []}
          withSplit
          createAction={createWriterInline}
          hiddenFieldName="writers_json"
        />
      </div>

      <div className="border-t border-console-border pt-6">
        <h2 className="mb-3 text-sm font-medium">Labels</h2>
        <MultiReferencePicker
          label="Labels"
          options={referenceData.labels}
          initialSelected={defaultValues?.labels ?? []}
          withSplit
          createAction={createLabelInline}
          hiddenFieldName="labels_json"
        />
      </div>

      <div className="border-t border-console-border pt-6">
        <label htmlFor="notes" className="mb-1 block text-sm text-console-text-muted">
          Notes
        </label>
        <textarea
          id="notes"
          name="notes"
          rows={4}
          defaultValue={defaultValues?.notes ?? ""}
          className={fieldClasses}
          placeholder="Anything a coordinator should know about clearing this song."
        />
      </div>

      <button
        type="submit"
        className="rounded-[var(--radius-pill)] bg-console-accent px-5 py-2 text-sm font-medium text-console-bg hover:bg-console-accent-strong"
      >
        {submitLabel}
      </button>
    </form>
  );
}
